import json
from dataclasses import asdict, replace
from pathlib import Path

import pytest

from ddsr_bench.benchmarks.critpt.data.schemas import AIProblemSpec, CritPtSource
from ddsr_bench.benchmarks.critpt.generation import prompts
from ddsr_bench.benchmarks.critpt.generation.prompts import parse_prompt, system_prompt
from ddsr_bench.benchmarks.critpt.generation.runner import initial_messages


@pytest.mark.parametrize("kind", ["auto", "freestyle"])
def test_ai_upstream(kind):
    # Generated by upstream build_solver_messages at 565d1b0; never calls a model.
    snapshots = Path(__file__).parent / "fixtures/ai-prompts.json"
    problem = AIProblemSpec(
        "ai-test",
        "main",
        None,
        "Find {{x}}.",
        "def answer():\n    return ...\n" if kind == "auto" else "",
        CritPtSource.AI,
        Path("test"),
        "Return {{x}}." if kind == "auto" else None,
        grader="rule" if kind == "auto" else "llm",
    )
    assert [asdict(m) for m in initial_messages(problem, "one-step")] == json.loads(
        snapshots.read_text()
    )[kind]


def test_system_styles() -> None:
    one_step = system_prompt("one-step")
    two_step = system_prompt("two-step")

    assert "**Parsing Structure**" in one_step
    assert "**Formatting Compliance**" not in one_step
    assert "**Formatting Compliance**" in two_step
    assert "**Parsing Structure**" not in two_step
    assert "at least 12 significant digits" in one_step


def test_parse_prompt() -> None:
    template = "def answer():\n    return {{value}}"
    rendered = parse_prompt(template)

    assert template in rendered
    assert rendered.startswith("Populate your final answer")
    assert rendered.endswith("\n```")


def test_rejects_unknown_style() -> None:
    with pytest.raises(ValueError, match="unknown prompt style"):
        system_prompt("three-step")  # type: ignore[arg-type]


@pytest.mark.parametrize("instructions", [None, "", " ", "Use {{literal}} notation."])
def test_ai_route(tmp_path, monkeypatch, instructions):
    path = tmp_path / "ai.yaml"
    path.write_text(
        "SOLVER_SYSTEM_PROMPT: {llm: Role.}\nANSWER_INSTRUCTIONS: Default.\n"
        "USER_PROMPT: '{{ statement }}: {{ instructions }}'\n"
    )
    monkeypatch.setitem(prompts._PATHS, CritPtSource.AI, path)
    expected = instructions if instructions and instructions.strip() else "Default."
    assert system_prompt("one-step", source=CritPtSource.AI, grader="llm") == "Role."
    problem = AIProblemSpec(
        "ai-test",
        "main",
        None,
        "Question",
        "",
        CritPtSource.AI,
        Path("test"),
        instructions,
        grader="llm",
    )
    assert prompts.user_prompt(problem, "one-step") == f"Question: {expected}"
    with pytest.raises(ValueError, match="requires one-step"):
        system_prompt("two-step", source=CritPtSource.AI)


def test_official_route():
    assert system_prompt("one-step", source="critpt") == system_prompt(
        "one-step", source=CritPtSource.OFFICIAL
    )
    with pytest.raises(ValueError, match="CritPtSource"):
        system_prompt("one-step", source="unknown")


@pytest.mark.parametrize("grader", [None, "unknown"])
def test_unknown_grader(grader):
    with pytest.raises(ValueError, match="unknown answer grader"):
        system_prompt("one-step", source=CritPtSource.AI, grader=grader)


@pytest.mark.parametrize("grader", ["rule", "llm"])
@pytest.mark.parametrize("template", ["", "def answer():\n    return ...\n"])
def test_grader_routing(grader, template):
    problem = AIProblemSpec(
        "ai-test",
        "main",
        None,
        "Question",
        template,
        CritPtSource.AI,
        Path("test"),
        "Instructions.",
        grader=grader,
    )
    messages = initial_messages(problem, "one-step")
    with pytest.raises(ValueError, match="unknown answer grader"):
        initial_messages(replace(problem, grader=None), "one-step")
    assert (
        messages[0].content
        == prompts.load_prompts(CritPtSource.AI)["SOLVER_SYSTEM_PROMPT"][grader]
    )
    label = (
        "Final answer instructions:" if grader == "rule" else "Response instructions:"
    )
    assert label in messages[1].content
    assert ("```python" in messages[1].content) == bool(template)
    assert prompts.user_prompt(replace(problem, code_template=""), "one-step").endswith(
        "Instructions."
    )
